"use client";

import { useRef, useState } from "react";

export default function Home() {
  const [photo, setPhoto] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [role, setRole] = useState("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoUpload = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = event.target.files?.[0];

    if (!file) return;

    if (!file.type.startsWith("image/")) {
      alert("Please select an image.");
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      alert("Image must be less than 10MB.");
      return;
    }

    const reader = new FileReader();

    reader.onload = () => {
      setPhoto(reader.result as string);
    };

    reader.readAsDataURL(file);
  };

  const scrollToBuilder = () => {
    document
      .getElementById("builder")
      ?.scrollIntoView({
        behavior: "smooth",
      });
  };

  return (
    <main className="hh-site">

      {/* =========================
          NAVIGATION
      ========================== */}

      <nav className="hh-navbar">

        <div className="brand-mark">

          <div className="brand-symbol">
            HH
          </div>

          <div className="brand-text">
            <strong>HACKER HOUSE</strong>
            <span>GOA · 2026</span>
          </div>

        </div>

        <div className="nav-links">

          <a href="#builder">
            BUILDER
          </a>

          <a href="#about">
            ABOUT
          </a>

          <button onClick={scrollToBuilder}>
            CREATE ID
          </button>

        </div>

      </nav>


      {/* =========================
          HERO
      ========================== */}

      <section className="hh-hero-new">

        <div className="hero-grid" />

        <div className="hero-orb hero-orb-one" />

        <div className="hero-orb hero-orb-two" />


        <div className="hero-content">

          <div className="hero-kicker">
            HACKER HOUSE · GOA · 2026
          </div>


          <h1>
            BUILD
            <br />

            <span>
              YOUR
            </span>

            <br />

            <em>
              ID.
            </em>
          </h1>


          <p className="hero-description">
            You build things. You ship things.
            You break things.
            <br />
            Now build yourself an official
            HH Goa 2026 Builder ID.
          </p>


          <div className="hero-details">

            <span>
              GOA, INDIA
            </span>

            <span>
              28 — 31 OCT 2026
            </span>

          </div>


          <button
            className="hero-button"
            onClick={scrollToBuilder}
          >
            CREATE MY BUILDER ID

            <span>
              →
            </span>

          </button>

        </div>


        {/* Decorative stamp */}

        <div className="hero-stamp">

          <span>
            BUILD
          </span>

          <span>
            SHIP
          </span>

          <span>
            BREAK
          </span>

        </div>


        <div className="hero-palm">
          🌴
        </div>

      </section>


      {/* =========================
          MARQUEE
      ========================== */}

      <div className="hh-marquee">

        <div>
          BUILD SOMETHING ★ SHIP SOMETHING ★
          BUILD SOMETHING ★ SHIP SOMETHING ★
          BUILD SOMETHING ★ SHIP SOMETHING ★
        </div>

      </div>


      {/* =========================
          BUILDER SECTION
      ========================== */}

      <section
        id="builder"
        className="builder-section"
      >

        <div className="section-heading">

          <div className="section-number">
            01
          </div>

          <div>

            <p>
              YOUR TURN
            </p>

            <h2>
              BUILD YOUR
              <br />
              BUILDER PASS.
            </h2>

          </div>

        </div>


        <div className="builder-layout">


          {/* =====================
              FORM
          ====================== */}

          <div className="builder-panel">

            <div className="panel-top">

              <span>
                BUILDER STUDIO
              </span>

              <span>
                STEP 01 / 03
              </span>

            </div>


            <div className="upload-heading">

              <h3>
                Who are you?
              </h3>

              <p>
                Tell us what you build.
              </p>

            </div>


            {/* PHOTO UPLOAD */}

            <div
              className="drop-zone"
              onClick={() =>
                fileInputRef.current?.click()
              }
            >

              <input
                ref={fileInputRef}
                type="file"
                accept="image/png,image/jpeg,image/webp"
                hidden
                onChange={handlePhotoUpload}
              />


              {photo ? (

                <div className="uploaded-photo">

                  <img
                    src={photo}
                    alt="Uploaded builder"
                  />

                  <div>

                    <strong>
                      PHOTO READY
                    </strong>

                    <small>
                      Click to replace
                    </small>

                  </div>

                </div>

              ) : (

                <>

                  <div className="upload-icon">
                    ↑
                  </div>

                  <strong>
                    DROP YOUR PHOTO
                  </strong>

                  <span>
                    or click to browse
                  </span>

                  <small>
                    JPG · PNG · WEBP · MAX 10MB
                  </small>

                </>

              )}

            </div>


            {/* NAME */}

            <div className="field">

              <label>
                FULL NAME
              </label>

              <input
                type="text"
                value={name}
                onChange={(event) =>
                  setName(event.target.value)
                }
                placeholder="e.g. Dipraj Biswas"
              />

            </div>


            {/* ROLE */}

            <div className="field">

              <label>
                STACK / ROLE
              </label>

              <input
                type="text"
                value={role}
                onChange={(event) =>
                  setRole(event.target.value)
                }
                placeholder="e.g. Full-Stack / AI / Founder"
              />

            </div>


            {/* GENERATE */}

            <button
              className="generate-button"
              onClick={() =>
                document
                  .getElementById("preview")
                  ?.scrollIntoView({
                    behavior: "smooth",
                  })
              }
            >

              GENERATE MY PASS

              <span>
                →
              </span>

            </button>


            <div className="builder-meta">

              <span>
                NO LOGIN
              </span>

              <span>
                FREE
              </span>

              <span>
                INSTANT
              </span>

            </div>

          </div>


          {/* =====================
              LIVE PREVIEW
          ====================== */}

          <div
            id="preview"
            className="preview-side"
          >

            <div className="preview-heading">

              <span>
                LIVE PREVIEW
              </span>

              <span>
                02 / 03
              </span>

            </div>


            <div className="builder-card">

              <div className="card-noise" />


              {/* CARD HEADER */}

              <div className="card-header">

                <strong>
                  HACKER HOUSE
                </strong>

                <span>
                  GOA · 2026
                </span>

              </div>


              {/* CARD PHOTO */}

              <div className="card-photo">

                {photo ? (

                  <img
                    src={photo}
                    alt="Builder"
                  />

                ) : (

                  <div className="card-placeholder">

                    YOUR
                    <br />
                    PHOTO

                  </div>

                )}

              </div>


              {/* CARD INFO */}

              <div className="card-info">

                <div className="card-label">
                  BUILDER
                </div>


                <h3>
                  {name || "YOUR NAME"}
                </h3>


                <p>
                  {role || "YOUR STACK / ROLE"}
                </p>

              </div>


              {/* CARD FOOTER */}

              <div className="card-footer">

                <span>
                  HH-GOA-2026
                </span>

                <span>
                  #FRAMEINGOA
                </span>

              </div>


              <div className="card-star">
                ★
              </div>

            </div>


            {/* SHARE */}

            <button className="share-button">

              SHARE MY PASS

              <span>
                ↗
              </span>

            </button>

          </div>

        </div>

      </section>


      {/* =========================
          ABOUT
      ========================== */}

      <section
        id="about"
        className="about-section"
      >

        <div className="about-big">

          MAKE
          <br />

          SOMETHING
          <br />

          WORTH

          <span>
            SHARING.
          </span>

        </div>


        <div className="about-copy">

          <p className="about-label">
            HH GOA · 2026
          </p>


          <p>
            This isn't just a profile card.
            It's proof that you were here,
            that you built something,
            and that you shipped it.
          </p>


          <button onClick={scrollToBuilder}>
            BUILD YOUR ID →
          </button>

        </div>

      </section>


      {/* =========================
          FOOTER
      ========================== */}

      <footer className="hh-footer-new">

        <div>
          HACKER HOUSE
        </div>

        <span>
          GOA · INDIA · 2026
        </span>

        <div>
          ★
        </div>

      </footer>

    </main>
  );
}